/* Ticket-regression: engine-side multi-prompt regression gate.
 *
 * Loads prompts.json (generated by gen_regression_ref.py), runs each prompt
 * through the engine (greedy), checks:
 *   1. greedy token ids match reference exactly
 *   2. last-token logits within tolerance (atol 0.15, cos > 0.9999)
 *
 * Usage: run_regression <model_dir> [regression_dir]
 * Not a ctest — requires the 28.7 GiB checkpoint. Run manually.
 */
#define _CRT_SECURE_NO_WARNINGS 1
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "q35/q35_model.h"
#include "q35/q35_json.h"
#include "q35_plat.h"

static unsigned char *slurp(const char *path, size_t *n) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); *n = (size_t)ftell(f); fseek(f, 0, SEEK_SET);
    unsigned char *b = malloc(*n ? *n : 1);
    if (*n && fread(b, 1, *n, f) != *n) { fclose(f); free(b); return NULL; }
    fclose(f); return b;
}

static int read_id_array(const JVal *arr, uint32_t *dst, int cap) {
    if (!arr || arr->t != J_ARR || (int)arr->v.arr.n > cap) return -1;
    for (size_t i = 0; i < arr->v.arr.n; i++)
        if (arr->v.arr.items[i]->t != J_NUM) return -1;
        else dst[i] = (uint32_t)arr->v.arr.items[i]->v.num;
    return (int)arr->v.arr.n;
}

int main(int argc, char **argv) {
    const char *model_dir = argc > 1 ? argv[1] : "../Qwen3.8-27B-FP8";
    const char *reg_dir = argc > 2 ? argv[2] : "tests/gates/real-22/regression";
    char path[512], errbuf[512]; int err, fails = 0;

    snprintf(path, sizeof path, "%s/prompts.json", reg_dir);
    size_t jn; char *jt = (char *)slurp(path, &jn);
    if (!jt) { printf("SKIP: no prompts.json in %s\n", reg_dir); return 77; }
    Q35Json *j = q35_json_parse(jt, jn);
    free(jt);
    if (!j) { printf("FAIL: prompts.json parse\n"); return 1; }
    const JVal *root = q35_json_root(j);
    int vocab = (int)q35_jnum(root, "vocab", &(int){0});
    int n_prompts = (int)q35_jnum(root, "prompts", &(int){0});
    const JVal *items = q35_obj_get(root, "items");
    if (!items || items->t != J_ARR || vocab <= 0) {
        printf("FAIL: prompts.json missing fields\n"); return 1;
    }

    double t0 = q35_plat_now();
    Q35Model *m = q35_model_load(model_dir, 0, errbuf, sizeof errbuf, &err);
    if (!m) { printf("FAIL load: %s (err=%d)\n", errbuf, err); return 1; }
    printf("loaded in %.1f s, vocab=%u\n", q35_plat_now() - t0, q35_model_vocab(m));

    float *lg = malloc((size_t)vocab * 4);
    float *ref = malloc((size_t)vocab * 4);
    double gmaxabs = 0, gmaxrel = 0;

    for (size_t pi = 0; pi < items->v.arr.n; pi++) {
        const JVal *item = items->v.arr.items[pi];
        uint32_t prompt_ids[256], gen_ids[32];
        int np = read_id_array(q35_obj_get(item, "prompt_ids"), prompt_ids, 256);
        int ng = read_id_array(q35_obj_get(item, "gen_ids"), gen_ids, 32);
        if (np <= 0 || ng <= 0) { printf("prompt %zu: bad ids\n", pi); fails++; continue; }

        /* load reference last-token logits */
        snprintf(path, sizeof path, "%s/logits_%zu.bin", reg_dir, pi);
        FILE *f = fopen(path, "rb");
        if (!f) { printf("prompt %zu: no ref logits\n", pi); fails++; continue; }
        fread(ref, 4, vocab, f); fclose(f);

        /* run engine: prefill prompt, greedy gen */
        q35_model_reset(m);
        int rc = q35_forward_prefill(m, (const int32_t *)prompt_ids, (size_t)np, lg);
        if (rc != Q35_MODEL_OK) { printf("prompt %zu: prefill rc=%d\n", pi, rc); fails++; continue; }

        int ids_ok = 1;
        for (int g = 0; g < ng; g++) {
            /* argmax */
            uint32_t best = 0; float bv = lg[0];
            for (int i = 1; i < vocab; i++) if (lg[i] > bv) { bv = lg[i]; best = i; }
            if (best != gen_ids[g]) {
                printf("prompt %zu: gen[%d] %u != ref %u\n", pi, g, best, gen_ids[g]);
                ids_ok = 0;
                best = gen_ids[g];  /* align with reference for logits comparison */
            }
            /* feed token back to advance to next position (except after
             * the last gen token — the current lg already corresponds to
             * rows[-1] of the HF reference at that point) */
            if (g + 1 < ng) {
                rc = q35_forward_decode(m, (int32_t)best, lg);
                if (rc != Q35_MODEL_OK) { printf("prompt %zu: decode rc=%d\n", pi, rc); ids_ok = 0; break; }
            }
        }

        /* compare last-token logits */
        double maxabs = 0, cos_num = 0, cos_den_r = 0, cos_den_e = 0;
        for (int i = 0; i < vocab; i++) {
            double d = fabs((double)lg[i] - ref[i]);
            if (d > maxabs) maxabs = d;
            cos_num += (double)lg[i] * ref[i];
            cos_den_r += (double)ref[i] * ref[i];
            cos_den_e += (double)lg[i] * lg[i];
        }
        double cos = cos_num / (sqrt(cos_den_r) * sqrt(cos_den_e) + 1e-30);
        if (maxabs > gmaxabs) gmaxabs = maxabs;
        int logits_ok = (maxabs <= 0.15 || cos > 0.999);

        const char *text = q35_jstr(item, "text");
        printf("prompt %2zu: %s  ids=%s  maxabs=%.4f cos=%.6f %s  [%s]\n",
               pi, ids_ok ? "OK" : "FAIL", ids_ok ? "exact" : "MISMATCH",
               maxabs, cos, logits_ok ? "OK" : "FAIL",
               text ? text : "(no text)");
        if (!logits_ok) fails++;
    }

    q35_model_free(m);
    free(lg); free(ref);
    q35_json_free(j);
    printf("---\n%d/%zu prompts passed | overall maxabs=%.4f\n",
           (int)items->v.arr.n - fails, items->v.arr.n, gmaxabs);
    printf("%s\n", fails ? "REGRESSION FAILED" : "ALL PASS");
    return fails ? 1 : 0;
}
